package br.com.onda;
import android.app.*;import android.content.*;import android.graphics.Bitmap;import android.net.Uri;import android.view.*;import android.view.inspector.WindowInspector;import android.widget.*;import androidx.core.content.FileProvider;import org.junit.*;import static org.junit.Assert.*;import static androidx.test.platform.app.InstrumentationRegistry.getInstrumentation;import java.io.*;import java.lang.reflect.Field;import java.util.UUID;import org.json.JSONObject;
/** Real menu clicks and native decoding in one test process; no timing-dependent coordinates. */
@android.annotation.TargetApi(29)
@androidx.media3.common.util.UnstableApi
public class VideoPipTest {
 private final Instrumentation ins=getInstrumentation();private final Context c=ins.getTargetContext();private VideoActivity screen;private File file;private boolean had,background;
 private interface Check{boolean ready()throws Exception;}
 private Object field(String name)throws Exception{Field f=VideoActivity.class.getDeclaredField(name);f.setAccessible(true);return f.get(screen);}
 private org.videolan.libvlc.MediaPlayer player()throws Exception{return (org.videolan.libvlc.MediaPlayer)field("video");}
 private void waitFor(Check check)throws Exception{for(int i=0;i<300;i++){boolean[] ready={false};ins.runOnMainSync(()->{try{ready[0]=check.ready();}catch(Exception e){throw new RuntimeException(e);}});if(ready[0])return;Thread.sleep(50);}fail("Native picture-in-picture scenario timed out");}
 private View find(View root,String desc){if(desc.contentEquals(root.getContentDescription()==null?"":root.getContentDescription()))return root;if(root instanceof ViewGroup)for(int i=0;i<((ViewGroup)root).getChildCount();i++){View v=find(((ViewGroup)root).getChildAt(i),desc);if(v!=null)return v;}return null;}
 private View window(String desc){for(View root:WindowInspector.getGlobalWindowViews()){View found=find(root,desc);if(found!=null&&found.getVisibility()==View.VISIBLE)return found;}return null;}
 @Test public void actualVideoMenuEntersPipKeepsPlayingAndExpands()throws Exception{
  SharedPreferences p=c.getSharedPreferences("video_controls",0);had=p.contains("background");background=p.getBoolean("background",true);p.edit().putBoolean("background",false).commit();File parent=new File(c.getCacheDir(),"shares/pip-test");parent.mkdirs();file=new File(parent,"native-pip-"+UUID.randomUUID()+".mp4");try(InputStream in=ins.getContext().getAssets().open("power-background.mp4");OutputStream out=new FileOutputStream(file)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}Uri uri=FileProvider.getUriForFile(c,c.getPackageName()+".share",file);screen=(VideoActivity)ins.startActivitySync(new Intent(c,VideoActivity.class).setAction(Intent.ACTION_VIEW).setDataAndType(uri,"video/mp4").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_GRANT_READ_URI_PERMISSION));waitFor(()->player()!=null&&player().isPlaying()&&(Boolean)field("framesSeen")&&player().getTime()>400);
  ins.runOnMainSync(()->{View menu=find(screen.findViewById(android.R.id.content),"Menu de vídeos");assertNotNull(menu);menu.performClick();});waitFor(()->window("Buscar no menu")!=null);ins.runOnMainSync(()->((EditText)window("Buscar no menu")).setText("Janela"));waitFor(()->window("Janela flutuante do vídeo")!=null);ins.runOnMainSync(()->window("Janela flutuante do vídeo").performClick());waitFor(()->screen.isInPictureInPictureMode()&&player().isPlaying());long[] time={0};ins.runOnMainSync(()->{try{time[0]=player().getTime();}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(1000);ins.runOnMainSync(()->{try{assertTrue(player().isPlaying());assertTrue(player().getTime()>time[0]+300);}catch(Exception e){throw new RuntimeException(e);}});Bitmap picture=ins.getUiAutomation().takeScreenshot();if(picture!=null)try(OutputStream out=new FileOutputStream(new File(c.getFilesDir(),"video-pip.png"))){picture.compress(Bitmap.CompressFormat.PNG,100,out);picture.recycle();}
  ins.runOnMainSync(()->c.startActivity(new Intent(c,VideoActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_REORDER_TO_FRONT)));waitFor(()->!screen.isInPictureInPictureMode()&&player().isPlaying());ins.runOnMainSync(()->{assertFalse(screen.isDestroyed());View pause=find(screen.findViewById(android.R.id.content),"Pausar vídeo");assertNotNull(pause);pause.performClick();});waitFor(()->!player().isPlaying());try(OutputStream out=new FileOutputStream(new File(c.getFilesDir(),"pip-tests.json"))){out.write(new JSONObject().put("entered",true).put("continuedPlaying",true).put("expanded",true).put("selectedThroughRealMenu",true).put("nativeFramesDecoded",true).put("sameActivityPreserved",true).toString(2).getBytes("UTF-8"));}
 }
 @After public void cleanup(){if(screen!=null){ins.runOnMainSync(screen::finish);ins.waitForIdleSync();}SharedPreferences.Editor e=c.getSharedPreferences("video_controls",0).edit();if(had)e.putBoolean("background",background);else e.remove("background");e.commit();if(file!=null)file.delete();}
}
